def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    start_index = 0
    stack = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack += 1
        elif char == ')':
            stack -= 1
        if stack == 0:
            groups.append(paren_string[start_index:i+1])
            start_index = i+1
    return groups

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def max_value_on_paths(N, grid_values):
    dp = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        dp[x][y] = v
    for i in range(N - 1, -1, -1):
        for j in range(N):
            dp[i][j] = max(dp[i + 1][j], dp[i][j + 1], dp[i + 1][j + 1]) + dp[i][j]
    return dp[0][0]

