def count_passing_ways(n, m):
    # Initialize a 2D list to store the dynamic programming states
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: after m passes, if n=1, then there is only 1 way to return to the starting student
    dp[m][1] = 1

    # Fill the dynamic programming table
    for i in range(m, 0, -1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i + 1][j - 1] + dp[i + 1][j + 1]

    return dp[1][1]

def polynomial_to_string(n, coeffs):
    result = ''
    for i in range(len(coeffs)):
        if coeffs[i] != 0:
            if coeffs[i] > 0:
                result += '+'
            result += f'{coeffs[i]}x'
            if n - i > 1:
                result += f'^{n - i}'
            elif n - i == 1:
                result += 'x'
            elif n - i == 0:
                result += ''
    return result[1:]

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort the applicants based on their test scores in descending order
    sorted_applicants = sorted(applicants, key=lambda x: x[1], reverse=True)

    # Calculate the interview score cutoff based on m * 1.5
    cutoff = int(m * 1.5)

    # Create a new list to store the qualified applicants
    qualified_applicants = []

    # Iterate over the sorted applicants and add those with scores equal to or higher than the cutoff to the qualified list
    for applicant in sorted_applicants:
        if applicant[1] >= cutoff:
            qualified_applicants.append(applicant)

    # Return the interview score cutoff and the qualified applicants
    return (cutoff, qualified_applicants)

def decode(encoded, original, message):
    # Store the mapping from encoded to original letters in a dictionary
    mapping = {}
    for i in range(len(encoded)):
        mapping[encoded[i]] = original[i]

    # Check if the mapping is valid by ensuring that all letters are represented
    if len(mapping) != len(set(original)):
        return "Failed"

    # Check if the message is valid by ensuring that it contains only letters in the encoded alphabet
    if not all(c in encoded for c in message):
        return "Failed"

    # Build the decoded message by looking up each encoded letter in the mapping
    decoded = ""
    for c in message:
        try:
            decoded += mapping[c]
        except KeyError:
            return "Failed"

    return decoded

def count_partitions(n, k, x):
    if k == 1:
        return 1
    if x >= n:
        return 0
    return count_partitions(n - x, k - 1, x) + count_partitions(n, k, x + 1)

def count_sequences(n, last, memo):
    if n not in memo:
        if n == last:
            memo[n] = 1
        else:
            memo[n] = 0
            for i in range(1, int(last/2)+1):
                memo[n] += count_sequences(n+i, last-i, memo)
    return memo[n]

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    for a in range(1, y0 // x0 + 1):
        if gcd(a, y0 // x0) == 1:
            b = y0 // (a * x0)
            if a == b:
                count += 1
            else:
                count += 2
    return count

def preorder_traversal(inorder, postorder):
    if not inorder:
        return ""

    stack = []
    result = []
    lookup = {}

    for i, char in enumerate(inorder):
        lookup[char] = i

    for char in postorder:
        stack.append(char)
        while stack and stack[-1] in lookup and lookup[stack[-1]] == len(inorder) - len(stack):
            result.append(stack.pop())

    return "".join(result)

def string_transformation(A, B, rules):
    visited = set()
    queue = [(A, 0)]
    while queue:
        current, steps = queue.pop(0)
        if current == B:
            return steps
        if current in visited:
            continue
        visited.add(current)
        for rule in rules:
            new_string = current.replace(rule[0], rule[1])
            queue.append((new_string, steps+1))
    return "NO ANSWER!"

