def remaining_trees_after_clearing(l, areas):
    # Initialize a list to store the positions of trees
    tree_positions = [i for i in range(l)]

    # Iterate through the areas to be cleared
    for start, end in areas:
        # Remove the trees in the current area
        tree_positions = [i for i in tree_positions if not (start <= i <= end)]

    # Return the total number of remaining trees
    return len(tree_positions)

